    equipamiento_disponible text[] DEFAULT '{}'::text[] NOT NULL,
    dias_disponibles_semana integer DEFAULT 3 NOT NULL,
    minutos_por_sesion integer DEFAULT 45 NOT NULL,
    onboarding_completado boolean DEFAULT false NOT NULL,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_perfil_objetivo_estandar CHECK ((objetivo_principal = ANY (ARRAY['Hipertrofia Muscular'::text, 'Fuerza MÔö£├¡xima'::text, 'Potencia y Explosividad'::text, 'Fuerza Resistencia'::text, 'Movilidad y Flexibilidad'::text, 'Estabilidad y Control Motor'::text, 'Acondicionamiento MetabÔö£Ôöélico'::text])))
);


